import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Timeline","description":"Einträge über zwei verknüpfte Grids hinweg auf einem Zeitstrahl darstellen.","frontmatter":{"title":"Timeline","description":"Einträge über zwei verknüpfte Grids hinweg auf einem Zeitstrahl darstellen."},"headers":[],"relativePath":"ansichten/timeline.md","filePath":"ansichten/timeline.md","lastUpdated":1786167924000}'),a={name:"ansichten/timeline.md"};function s(d,e,l,o,h,u){return n(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h1><p>Die <strong>Timeline</strong> stellt Einträge auf einem Zeitstrahl dar — mit Start- und Enddatum, in Zeilen gruppiert.</p><p><strong>Geeignet für:</strong> Projektplanung, Belegungspläne, Ressourcenübersichten, Personaleinsatz.</p><div class="warning custom-block"><p class="custom-block-title">Tarifabhängig</p><p>Die Timeline steht nicht in allen Tarifen zur Verfügung. Der Upgrade-Hinweis lautet <em>Upgraden Sie auf Pro, um Timeline Ansichten hinzuzufügen.</em></p></div><h2 id="voraussetzungen" tabindex="-1">Voraussetzungen <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Voraussetzungen&quot;">​</a></h2><p>Die Timeline ist die <strong>einzige Ansicht, die über zwei Grids hinweg konfiguriert wird</strong>. Das macht sie mächtiger, aber auch aufwendiger einzurichten als alle anderen.</p><div class="tip custom-block"><p class="custom-block-title">Der Aufbau ist beabsichtigt</p><p>Ein Zeitstrahl braucht <strong>Zeilen</strong> und <strong>Balken</strong> — und das sind zwei verschiedene Dinge: Räume und Buchungen, Mitarbeitende und Einsätze, Maschinen und Aufträge. In einem einzelnen Grid ließe sich das nicht ausdrücken.</p><p>Planen Sie Ihr Datenmodell deshalb von Anfang an mit zwei Grids, wenn Sie eine Timeline brauchen.</p></div><div class="warning custom-block"><p class="custom-block-title">Zwei Bedingungen müssen erfüllt sein</p><p><strong>1. Ein Feld vom Typ <em>Mehrere Einträge verknüpfen</em></strong> im Grid, auf dem die Ansicht liegt.</p><blockquote><p><em>Um eine Timeline zu sehen, muss Ihr Grid eine Spalte vom Typ Mehrfachreferenz besitzen.</em></p></blockquote><p><strong>2. Datumsfelder im verknüpften Grid</strong> — dort liegen Start und Ende.</p><blockquote><p><em>Das referenzierte Grid hat keine Datums- oder Datumszeitfelder.</em></p></blockquote></div><div class="tip custom-block"><p class="custom-block-title">Wo „Mehrfachreferenz&quot; herkommt</p><p>Die Meldung verwendet den Begriff <em>Mehrfachreferenz</em>. Gemeint ist der Spaltentyp, der sonst überall <strong>Mehrere Einträge verknüpfen</strong> heißt. → <a href="/grids/verknuepfungen">Grids verknüpfen</a></p></div><h2 id="der-aufbau" tabindex="-1">Der Aufbau <a class="header-anchor" href="#der-aufbau" aria-label="Permalink to &quot;Der Aufbau&quot;">​</a></h2><p>Ein Beispiel für einen Belegungsplan:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grid „Räume&quot;                    Grid „Buchungen&quot;</span></span>
<span class="line"><span>├── Name                        ├── Titel</span></span>
<span class="line"><span>└── Buchungen  ←────────────────┤ Raum</span></span>
<span class="line"><span>    (Mehrere Einträge           ├── Von      (Datum)</span></span>
<span class="line"><span>     verknüpfen)                └── Bis      (Datum)</span></span></code></pre></div><p>Die Timeline liegt auf <strong>„Räume&quot;</strong>:</p><ul><li>Jeder Raum wird zu einer <strong>Zeile</strong> des Zeitstrahls.</li><li>Die verknüpften <strong>Buchungen</strong> erscheinen als Balken darin.</li><li>Deren Start- und Enddatum bestimmen Lage und Länge.</li></ul><div class="tip custom-block"><p class="custom-block-title">Das Denkmodell</p><p>Das Grid mit der Timeline liefert die <strong>Zeilen</strong>, das verknüpfte Grid die <strong>Balken</strong>.</p><p>Bauen Sie das Datenmodell also von der Frage her: <em>Was soll untereinander stehen?</em> Räume, Mitarbeitende, Maschinen, Projekte — das ist das Grid, auf dem die Ansicht liegt.</p></div><h2 id="einrichten" tabindex="-1">Einrichten <a class="header-anchor" href="#einrichten" aria-label="Permalink to &quot;Einrichten&quot;">​</a></h2><ol><li>Legen Sie beide Grids an und verknüpfen Sie sie über <strong>Mehrere Einträge verknüpfen</strong>.</li><li>Sorgen Sie dafür, dass das verknüpfte Grid Datumsfelder für Start und Ende hat.</li><li>Wählen Sie unter dem ersten Grid <strong>Ansicht erstellen</strong> → <strong>Timeline</strong>.</li><li>Öffnen Sie <strong>Timeline</strong> und konfigurieren Sie:</li></ol><p>Der Dialog heißt <em>Timeline konfigurieren</em>:</p><blockquote><p><em>Wählen Sie ein Referenzfeld und Datumsfelder aus, um die Timeline zu erstellen.</em></p></blockquote><table tabindex="0"><thead><tr><th>Einstellung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Referenzfeld</strong></td><td>Die Verknüpfungsspalte, aus der die Balken kommen</td></tr><tr><td><strong>Startdatum</strong></td><td>Datumsfeld im verknüpften Grid</td></tr><tr><td><strong>Enddatum</strong></td><td>Datumsfeld im verknüpften Grid</td></tr></tbody></table><p>Speichern mit <strong>Speichern</strong>. Fehlt die Verknüpfung, bietet ApptiveGrid <strong>Referenzfeld hinzufügen</strong> an.</p><h2 id="in-der-timeline-arbeiten" tabindex="-1">In der Timeline arbeiten <a class="header-anchor" href="#in-der-timeline-arbeiten" aria-label="Permalink to &quot;In der Timeline arbeiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th></th></tr></thead><tbody><tr><td><strong>Zeitraster</strong></td><td><em>Tag</em>, <em>Woche</em>, <em>Monat</em>, <em>Jahr</em></td></tr><tr><td><strong>Heute</strong></td><td>Springt zum aktuellen Datum</td></tr><tr><td><strong>Zeile</strong></td><td>Überschrift der Zeilenspalte</td></tr></tbody></table><p>Einträge ohne Titel erscheinen als <strong>Unbenannt</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Raster nach Planungshorizont</p><ul><li><strong>Tag</strong> für Tagesplanung mit Uhrzeiten</li><li><strong>Woche</strong> für die operative Einsatzplanung</li><li><strong>Monat</strong> für Projektphasen</li><li><strong>Jahr</strong> für Jahresplanung und Auslastung</li></ul><p>Das Jahresraster hat keine andere Ansicht — dafür ist die Timeline das einzige Werkzeug.</p></div><h2 id="timeline-oder-kalender" tabindex="-1">Timeline oder Kalender? <a class="header-anchor" href="#timeline-oder-kalender" aria-label="Permalink to &quot;Timeline oder Kalender?&quot;">​</a></h2><p>Beide stellen Zeit dar, lösen aber Unterschiedliches:</p><table tabindex="0"><thead><tr><th></th><th><a href="/ansichten/kalender">Kalender</a></th><th>Timeline</th></tr></thead><tbody><tr><td>Grundlage</td><td>ein Datumsfeld im eigenen Grid</td><td>Verknüpfung plus zwei Datumsfelder im Zielgrid</td></tr><tr><td>Aufbau</td><td>ein Grid</td><td><strong>zwei Grids</strong></td></tr><tr><td>Darstellung</td><td>Kalenderblatt</td><td>Zeitstrahl mit Zeilen</td></tr><tr><td>Raster</td><td>Tag, Woche, Monat</td><td>Tag, Woche, Monat, <strong>Jahr</strong></td></tr><tr><td>Stärke</td><td>Termine</td><td><strong>Auslastung und Überschneidungen</strong></td></tr><tr><td>Tarif</td><td>in allen Tarifen</td><td>tarifabhängig</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Wann sich der Aufwand lohnt</p><p>Wollen Sie nur Termine sehen, nehmen Sie den Kalender — er ist in einer Minute eingerichtet.</p><p>Die Timeline lohnt sich, wenn Sie <strong>nebeneinanderliegende Belegungen</strong> vergleichen wollen: Welcher Raum ist frei? Welche Maschine ist überbucht? Wer hat wann Kapazität? Genau das zeigt ein Kalender nicht.</p></div><h2 id="wenn-nichts-erscheint" tabindex="-1">Wenn nichts erscheint <a class="header-anchor" href="#wenn-nichts-erscheint" aria-label="Permalink to &quot;Wenn nichts erscheint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Ursache</th></tr></thead><tbody><tr><td><em>Um eine Timeline zu sehen, muss Ihr Grid eine Spalte vom Typ Mehrfachreferenz besitzen.</em></td><td>Keine Spalte <em>Mehrere Einträge verknüpfen</em> vorhanden</td></tr><tr><td><em>Das referenzierte Grid hat keine Datums- oder Datumszeitfelder.</em></td><td>Im Zielgrid fehlen Datumsfelder</td></tr><tr><td>Zeilen ohne Balken</td><td>Die Einträge haben keine Verknüpfung, oder deren Datumsfelder sind leer</td></tr><tr><td>Balken an falscher Stelle</td><td>Start- und Enddatum vertauscht</td></tr><tr><td>Ansicht lässt sich nicht anlegen</td><td>Tarif prüfen</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Datenlücken finden</p><p>Ein Filter <code>Von</code> <em>ist leer</em> im verknüpften Grid zeigt alle Einträge, die auf der Timeline nicht erscheinen können. → <a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li><li><a href="/ansichten/kalender">Kalender</a></li><li><a href="/grids/verknuepfungen">Grids verknüpfen</a></li></ul>`,34)])])}const g=t(a,[["render",s]]);export{m as __pageData,g as default};
